import { motion } from 'framer-motion';
import { ExternalLink, Code2 } from 'lucide-react';

const Projects = () => {
  const projectData = [
    {
      title: "AI-Powered Static Code Analysis",
      date: "Nov'25-Jan 26",
      desc: "Architected backend services using FastAPI to detect security vulnerabilities like SQL injection via AST parsing.",
      tech: ["Python", "NLP", "FastAPI", "React", "Docker"],
      link: "https://github.com/agrawal508"
    },
    {
      title: "AI Social Matching System",
      date: "Aug 25-Oct 25",
      desc: "Implemented an SVM-based audio classification model to distinguish between speech, music, and noise.",
      tech: ["Machine Learning", "Flask", "React", "MongoDB"],
      link: "https://github.com/agrawal508"
    },
    {
      title: "Employee Attrition Prediction",
      date: "Jun'25-Jul'25",
      desc: "Constructed an ML system using ensemble techniques to visualize employee risk metrics on a dashboard.",
      tech: ["Scikit-learn", "Pandas", "FastAPI", "Streamlit"],
      link: "https://github.com/agrawal508"
    }
  ];

  return (
    <section id="projects" className="py-24 px-10 bg-white">
      <div className="container mx-auto">
        <div className="flex justify-between items-end mb-16">
          <div>
            <h2 className="text-5xl font-black tracking-tighter uppercase">Selected Work</h2>
            <p className="text-gray-500 mt-2 font-medium">Focused on AI, Security, and Scalability</p>
          </div>
          <div className="hidden md:block h-1 w-1/3 bg-gray-100 rounded-full mb-4"></div>
        </div>

        <div className="grid md:grid-cols-1 gap-12">
          {projectData.map((project, index) => (
            <motion.div 
              key={index}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="group relative grid md:grid-cols-2 gap-8 p-8 rounded-3xl border border-gray-100 hover:border-black transition-all duration-500"
            >
              <div>
                <span className="text-sm font-bold text-gray-400">{project.date}</span>
                <h3 className="text-3xl font-bold mt-2 mb-4 group-hover:text-blue-600 transition-colors">{project.title}</h3>
                <p className="text-gray-600 leading-relaxed mb-6">{project.desc}</p>
                <div className="flex flex-wrap gap-2">
                  {project.tech.map(t => (
                    <span key={t} className="px-3 py-1 bg-gray-100 rounded-md text-xs font-bold uppercase tracking-wider">{t}</span>
                  ))}
                </div>
              </div>
              <div className="flex items-center justify-center md:justify-end gap-4">
                <a href={project.link} className="flex items-center gap-2 bg-black text-white px-6 py-3 rounded-full font-bold hover:bg-blue-600 transition-all">
                  <Code2 size={18} /> Code
                </a>
                <button className="p-3 border-2 border-gray-200 rounded-full hover:border-black transition-all">
                  <ExternalLink size={20} />
                </button>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;
